frappe.ui.form.on('Issue', {
	after_save(frm) {
	   if(frm.doc.escalation_date === null){
	       if(frm.doc.issue_type === "IT"){
	           frm.doc.escalation_date = frappe.datetime.now_datetime();
	           frm.refresh_field('escalation_date');
	        }
	    }
	}
});

frappe.ui.form.on('Project', {
	refresh(frm) {
		frm.add_custom_button('Fetch Updates', function(){
			frm.trigger("send_to_it");
	    });
    },
    send_to_it: function(frm){
     if(frm.doc.update_form === 0){
         cur_frm.set_value("update_form",1);
     }else if(frm.doc.update_form === 1){
         cur_frm.set_value("update_form",2);
     }else if(frm.doc.update_form === 2){
         cur_frm.set_value("update_form",1);
    }

    cur_frm.save();
    //cur_frm.refresh();
    }
});

frappe.ui.form.on('Warehouse Request', {
	refresh(frm) {
		frm.add_custom_button('Send to IT', function(){
			frm.trigger("send_to_it");
	    });
    },
    send_to_it: function(frm){
        console.log( frm.get_docinfo().assignments);
        frappe.db.insert({
            doctype: 'Issue',
            subject: 'Connectivity for '+ frm.doc.subject,
            related_warehouse_request: frm.doc.name,
            related_deployment: frm.doc.related_project,
            issue_type: 'Desktop Support',
            case_reason: 'Desktop Support',
            case_sub_reason: 'Connectivity',
            connectivity_type: frm.doc.connectivity,
            connectivity_devices_quantity: frm.doc.connectivity_device_quantity,
            machine_name: frm.doc.machine_names,
            customer: frm.doc.customer,
            deployment_owner: frm.doc.owner

        }).then(doc => {
            console.log(doc);
        });

    }
});

