frappe.ui.form.on("Warehouse Request", {
    onload(frm) {
        if (!window._wr_router_listener) {
            window._wr_router_listener = true;

            frappe.router.on("change", () => {
                const route = frappe.get_route();
                if (route && route[0] === "Form" && route[1] === "Warehouse Request") {
                    const flag = "wr_cache_cleared";
                    const wasCleared = sessionStorage.getItem(flag);

                    console.log("WR route change detected, wasCleared:", wasCleared);

                    if (!wasCleared) {
                        sessionStorage.setItem(flag, "1");
                        frappe.ui.toolbar.clear_cache();
                    } else {
                        // Reset so the NEXT navigation triggers a clear again
                        sessionStorage.removeItem(flag);
                    }
                }
            });
        }
    }
});

frappe.ui.form.on('Item', {
    refresh(frm) {
        frm.add_custom_button(__('Test iCorpAPI'), function() {
            frappe.call({
                method: 'icorp-dev-api-test',
                callback: function(r) {
                    frappe.msgprint({
                        title: __('iCorpAPI Test Result'),
                        message: '<pre>' + JSON.stringify(r.message, null, 2) + '</pre>',
                        indicator: 'green'
                    });
                },
                error: function(r) {
                    frappe.msgprint({
                        title: __('iCorpAPI Test Failed'),
                        message: '<pre>' + JSON.stringify(r, null, 2) + '</pre>',
                        indicator: 'red'
                    });
                }
            });
        });
    }
});
